  --font-sans: Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-serif: Lora, Georgia, serif;
  --font-mono: 'Menlo', 'Monaco', 'Courier New', monospace;
  --radius: .5rem; /* 8px */
  --shadow-2xs: 0px 1px 2px 0px hsl(220 13% 13% / 0.05);
  --shadow-xs: 0px 1px 3px 0px hsl(220 13% 13% / 0.10);
  --shadow-sm: 0px 1px 2px 0px hsl(220 13% 13% / 0.06), 0px 1px 3px 0px hsl(220 13% 13% / 0.10);
  --shadow: 0px 1px 3px 0px hsl(220 13% 13% / 0.10), 0px 1px 2px -1px hsl(220 13% 13% / 0.10);
  --shadow-md: 0px 4px 6px -1px hsl(220 13% 13% / 0.10), 0px 2px 4px -2px hsl(220 13% 13% / 0.10);
  --shadow-lg: 0px 10px 15px -3px hsl(220 13% 13% / 0.10), 0px 4px 6px -4px hsl(220 13% 13% / 0.10);
  --shadow-xl: 0px 20px 25px -5px hsl(220 13% 13% / 0.10), 0px 8px 10px -6px hsl(220 13% 13% / 0.10);
  --shadow-2xl: 0px 25px 50px -12px hsl(220 13% 13% / 0.25);
  --tracking-normal: 0em;
  --spacing: 0.25rem;

  /* Automatically computed borders - intensity can be controlled by the user by the --opaque-button-border-intensity setting */

